from pathlib import Path
import zlib,base64,json,hashlib
root=Path(r'C:\Users\brand\OneDrive\Documents\dead-street\tools\faction_audio_preview_20260914')
payload=""
files=json.loads(zlib.decompress(base64.b64decode(payload)))
receipt={}
for rel,source in files.items():
    p=root/rel
    p.parent.mkdir(parents=True,exist_ok=True)
    p.write_bytes(source.encode('utf-8'))
    receipt[rel]=hashlib.sha256(p.read_bytes()).hexdigest()
(root/'source_transfer_receipt.json').write_text(json.dumps(receipt,indent=2),encoding='utf-8')
print('Verified source transfer:',len(receipt),'files')
